+import { readFile } from "node:fs/promises";
+import { extname } from "node:path";
+import { TEXT_EXTENSIONS } from "./file-classifier";
+
+const MAX_TEXT_BYTES = 512 * 1024;
+const MAX_BINARY_SCAN_BYTES = 16 * 1024;
+
+export interface ExtractedContent {
+  text: string;
+  truncated: boolean;
+  strategy: string;
+}
+
+export async function extractContent(path: string, size: number): Promise<ExtractedContent> {
+  const ext = extname(path).toLowerCase();
+
+  if (TEXT_EXTENSIONS.has(ext) && size <= MAX_TEXT_BYTES * 8) {
+    const buffer = await readFile(path);
+    const text = buffer.toString("utf8").replace(/\u0000/g, "");
+    return {
+      text: text.slice(0, MAX_TEXT_BYTES),
+      truncated: text.length > MAX_TEXT_BYTES,
+      strategy: "text"
+    };
+  }
+
+  if ([".pdf", ".doc", ".docx", ".ppt", ".pptx", ".xls", ".xlsx"].includes(ext)) {
+    return {
+      text: await extractOfficeLikeText(path, size),
+      truncated: true,
+      strategy: "binary-metadata"
+    };
+  }
+
+  if (size <= MAX_BINARY_SCAN_BYTES) {
+    const buffer = await readFile(path);
+    const asText = buffer.toString("utf8");
+    const printable = asText.replace(/[^\x09\x0A\x0D\x20-\x7E\u4e00-\u9fa5]/g, " ").replace(/\s+/g, " ").trim();
+    if (printable.length > 24) {
+      return { text: printable.slice(0, MAX_BINARY_SCAN_BYTES), truncated: printable.length > MAX_BINARY_SCAN_BYTES, strategy: "small-binary-sniff" };
+    }
+  }
+
+  return { text: "", truncated: false, strategy: "metadata-only" };
+}
+
+async function extractOfficeLikeText(path: string, size: number): Promise<string> {
+  const buffer = await readFile(path, { encoding: null });
+  const sample = buffer.subarray(0, Math.min(size, MAX_TEXT_BYTES));
+  const text = sample
+    .toString("latin1")
+    .replace(/[^\x09\x0A\x0D\x20-\x7E\u4e00-\u9fa5]/g, " ")
+    .replace(/\s+/g, " ")
+    .trim();
+  return text.length > 40 ? text.slice(0, MAX_TEXT_BYTES) : "";
+}
