+type ProgressListener = (progress: ScanProgress) => void;
+
+export class FileScanner {
+  private readonly listeners = new Set<ProgressListener>();
+
+  constructor(private readonly repo: AppRepository) {}
+
+  onProgress(listener: ProgressListener): () => void {
+    this.listeners.add(listener);
+    return () => this.listeners.delete(listener);
+  }
+
+  async scan(folderId: string): Promise<ScanProgress> {
+    const folder = this.repo.folders.find(folderId);
+    if (!folder) throw new Error("Managed folder not found");
+
+    const startedAt = new Date().toISOString();
+    const progress: ScanProgress = {
+      folderId,
+      status: "scanning",
+      scannedFiles: 0,
+      indexedFiles: 0,
+      skippedFiles: 0,
+      currentPath: null,
+      message: "开始扫描",
+      startedAt,
+      finishedAt: null
+    };
+
+    this.repo.folders.updateStatus(folderId, "scanning");
+    this.emit(progress);
+
+    const seenPaths: string[] = [];
+    try {
+      for await (const filePath of walkFiles(folder)) {
+        progress.scannedFiles += 1;
+        progress.currentPath = filePath;
+        progress.message = "正在索引文件";
+        this.emit(progress);
+
+        try {
+          const file = await this.indexFile(folder, filePath);
+          this.repo.files.upsert(file);
+          seenPaths.push(filePath);
+          progress.indexedFiles += 1;
+        } catch (error) {
+          progress.skippedFiles += 1;
+          progress.message = error instanceof Error ? error.message : "索引失败";
+        }
+      }
+
+      this.repo.files.removeMissing(folderId, seenPaths);
+      this.repo.folders.markScanned(folderId, progress.indexedFiles);
+      progress.status = "ready";
+      progress.message = "扫描完成";
+      progress.finishedAt = new Date().toISOString();
+      progress.currentPath = null;
+      this.emit(progress);
+      return progress;
+    } catch (error) {
+      const message = error instanceof Error ? error.message : "扫描失败";
+      this.repo.folders.updateStatus(folderId, "error", message);
+      progress.status = "error";
+      progress.message = message;
+      progress.finishedAt = new Date().toISOString();
+      this.emit(progress);
+      return progress;
+    }
+  }
