+  private async indexFile(folder: ManagedFolder, filePath: string): Promise<FileRecord> {
+    const stats = await stat(filePath);
+    const name = basename(filePath);
+    const relativePath = buildRelativePath(folder, filePath);
+    const extracted = await extractContent(filePath, stats.size);
+    const category = categorizeFile(name, extracted.text);
+    const { riskLevel, riskReasons } = inferRisk(filePath, name);
+    const tags = inferTags(name, category, extracted.text);
+    if (extracted.truncated) tags.push("摘要截断");
+
+    return {
+      id: stableFileId(folder.id, filePath),
+      folderId: folder.id,
+      path: filePath,
+      relativePath,
+      name,
+      extension: extname(name).toLowerCase(),
+      mimeHint: inferMimeHint(name),
+      size: stats.size,
+      modifiedAt: stats.mtime.toISOString(),
+      createdAt: stats.birthtime.toISOString(),
+      indexedAt: new Date().toISOString(),
+      contentHash: await hashFile(filePath, stats.size),
+      hashKind: stats.size <= 50 * 1024 * 1024 ? "content" : "metadata",
+      summary: summarizeFile(name, extracted.text, stats.size),
