+async function* walkFiles(folder: ManagedFolder, current = folder.path): AsyncGenerator<string> {
+  const entries = await readdir(current, { withFileTypes: true });
+  for (const entry of entries) {
+    const fullPath = join(current, entry.name);
+    if (shouldSkip(folder, entry.name, fullPath)) continue;
+    if (entry.isDirectory()) {
+      yield* walkFiles(folder, fullPath);
+      continue;
+    }
+    if (entry.isFile()) {
+      yield fullPath;
+    }
+  }
+}
