+import type { ExecuteProposalResult, OperationLog, OrganizationProposal } from "@shared/types";
+import type { AppRepository } from "@main/db/repositories";
+
+export class ExecutionService {
+  constructor(private readonly repo: AppRepository) {}
+
+  async executeProposal(id: string): Promise<ExecuteProposalResult> {
+    const proposal = this.repo.proposals.find(id);
+    if (!proposal) throw new Error("Proposal not found");
+    if (proposal.status === "executed") {
+      return { proposal, operations: [] };
+    }
+
+    const operations: OperationLog[] = [];
+    for (const item of proposal.items) {
+      if (item.status !== "pending") continue;
+
+      if (item.action === "keep" || item.action === "tag") {
+        this.repo.proposals.updateItemStatus(item.id, "executed");
+        operations.push(
+          this.repo.operations.create({
+            proposalId: proposal.id,
+            proposalItemId: item.id,
+            action: item.action,
+            sourcePath: item.sourcePath,
+            targetPath: item.targetPath,
+            status: "executed",
+            error: null
+          })
+        );
+        continue;
+      }
+
+      if (!item.targetPath) {
+        this.repo.proposals.updateItemStatus(item.id, "failed", [...item.warnings, "缺少目标路径"]);
+        operations.push(this.failedOperation(proposal.id, item.id, item.action, item.sourcePath, item.targetPath, "缺少目标路径"));
+        continue;
+      }
+
+      try {
+        await access(item.sourcePath, constants.R_OK | constants.W_OK);
+        await assertTargetAvailable(item.targetPath);
+        await mkdir(dirname(item.targetPath), { recursive: true });
+        await rename(item.sourcePath, item.targetPath);
+        this.repo.proposals.updateItemStatus(item.id, "executed");
+        operations.push(
+          this.repo.operations.create({
+            proposalId: proposal.id,
+            proposalItemId: item.id,
+            action: item.action,
+            sourcePath: item.sourcePath,
+            targetPath: item.targetPath,
+            status: "executed",
+            error: null
+          })
+        );
+      } catch (error) {
+        const message = error instanceof Error ? error.message : "执行失败";
+        this.repo.proposals.updateItemStatus(item.id, "failed", [...item.warnings, message]);
+        operations.push(this.failedOperation(proposal.id, item.id, item.action, item.sourcePath, item.targetPath, message));
+      }
+    }
+
+    const refreshed = this.repo.proposals.find(id);
+    if (!refreshed) throw new Error("Proposal disappeared after execution");
+    const hasFailed = refreshed.items.some((item) => item.status === "failed");
+    const hasPending = refreshed.items.some((item) => item.status === "pending");
+    const status = hasPending || hasFailed ? "partially_executed" : "executed";
+    const updated = this.repo.proposals.updateStatus(id, status);
+    return { proposal: updated, operations };
+  }
+
+  async undoOperation(id: string): Promise<OperationLog> {
+    const operation = this.repo.operations.find(id);
+    if (!operation) throw new Error("Operation not found");
+    if (operation.status !== "executed") throw new Error("只能撤销已执行的操作");
+
+    if ((operation.action === "move" || operation.action === "rename") && operation.targetPath) {
+      await access(operation.targetPath, constants.R_OK | constants.W_OK);
+      await assertTargetAvailable(operation.sourcePath);
+      await mkdir(dirname(operation.sourcePath), { recursive: true });
+      await rename(operation.targetPath, operation.sourcePath);
+    }
+
+    return this.repo.operations.markUndone(id);
+  }
+
+  private failedOperation(
+    proposalId: string,
+    proposalItemId: string,
+    action: OperationLog["action"],
+    sourcePath: string,
+    targetPath: string | null,
+    error: string
+  ): OperationLog {
+    return this.repo.operations.create({
+      proposalId,
+      proposalItemId,
+      action,
+      sourcePath,
+      targetPath,
+      status: "failed",
+      error
+    });
+  }
