  useEffect(() => {
    window.smartFileAgent.listFiles(undefined, 80).then(setFiles).catch(() => undefined);
  }, []);

  return (
    <section className="panel full">
      <div className="searchbar">
        <Search size={18} />
        <input value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => event.key === "Enter" && search()} placeholder="搜索文件名、摘要、标签或全文片段" />
