          <span>文件</span>
          <span>分类</span>
          <span>风险</span>
          <span>摘要</span>
        </div>
        {files.map((file) => (
          <button key={file.id} className="file-row" onClick={() => window.smartFileAgent.revealPath(file.path)}>
            <span>
              <strong>{file.name}</strong>
              <small>{file.relativePath}</small>
            </span>
            <span>{file.category}</span>
            <span><RiskBadge risk={file.riskLevel} /></span>
            <span>{file.summary}</span>
          </button>
