import { app, BrowserWindow, dialog, ipcMain, shell } from "electron";
import { basename, resolve } from "node:path";
import { stat } from "node:fs/promises";
import type { LlmSettings, SmartFileAgentApi } from "@shared/types";
import type { AppRepository } from "./db/repositories";
import type { FileScanner } from "./services/file-scanner";
import type { RuleService } from "./services/rule-service";
import type { ProposalService } from "./services/proposal-service";
import type { ExecutionService } from "./services/execution-service";

type ApiMethod = keyof SmartFileAgentApi;

export function registerIpcHandlers(deps: {
  repo: AppRepository;
  scanner: FileScanner;
  ruleService: RuleService;
  proposalService: ProposalService;
  executionService: ExecutionService;
}): void {
  const { repo, scanner, ruleService, proposalService, executionService } = deps;

  ipcMain.handle(channel("chooseFolder"), async () => {
    const result = await dialog.showOpenDialog({
      title: "选择要交给 Smart File Agent 管理的文件夹",
      properties: ["openDirectory", "createDirectory"]
    });
    return result.canceled ? null : result.filePaths[0];
  });

  ipcMain.handle(channel("getSnapshot"), async () => repo.snapshot());

  ipcMain.handle(channel("addManagedFolder"), async (_event, path: string) => {
    const normalized = resolve(path);
    const stats = await stat(normalized);
    if (!stats.isDirectory()) throw new Error("请选择文件夹");
    return repo.folders.create(normalized, basename(normalized) || normalized);
  });

  ipcMain.handle(channel("removeManagedFolder"), async (_event, id: string) => {
    repo.folders.remove(id);
  });

  ipcMain.handle(channel("scanFolder"), async (_event, id: string) => scanner.scan(id));

  ipcMain.handle(channel("searchFiles"), async (_event, query: string, limit?: number) => repo.files.search(query, limit));

  ipcMain.handle(channel("listFiles"), async (_event, folderId?: string, limit?: number) => repo.files.list(folderId, limit));

  ipcMain.handle(channel("createRule"), async (_event, input) => ruleService.create(input));

  ipcMain.handle(channel("updateRule"), async (_event, rule) => ruleService.update(rule));

  ipcMain.handle(channel("deleteRule"), async (_event, id: string) => repo.rules.delete(id));

  ipcMain.handle(channel("generateProposal"), async (_event, input) => proposalService.generate(input ?? {}));

  ipcMain.handle(channel("executeProposal"), async (_event, id: string) => executionService.executeProposal(id));

  ipcMain.handle(channel("rejectProposal"), async (_event, id: string) => repo.proposals.updateStatus(id, "rejected"));

  ipcMain.handle(channel("undoOperation"), async (_event, id: string) => executionService.undoOperation(id));

  ipcMain.handle(channel("getLlmSettings"), async () => repo.settings.getLlmSettings());

  ipcMain.handle(channel("saveLlmSettings"), async (_event, settings: Omit<LlmSettings, "apiKeyStored" | "updatedAt"> & { apiKey?: string }) =>
    repo.settings.saveLlmSettings(settings)
  );

  ipcMain.handle(channel("revealPath"), async (_event, path: string) => {
    shell.showItemInFolder(path);
  });

  scanner.onProgress((progress) => {
    for (const win of BrowserWindow.getAllWindows()) {
      win.webContents.send("sfa:scanProgress", progress);
    }
  });
}

