import { randomUUID } from "node:crypto";
import { basename, dirname, join } from "node:path";
import type {
  FileRecord,
  GenerateProposalInput,
  OrganizationProposal,
  OrganizationProposalItem,
  UserPreferenceRule
} from "@shared/types";
import type { AppRepository } from "@main/db/repositories";
import { isLikelyDownloadFolder, isRootLooseFile } from "./file-classifier";

const DEFAULT_LIMIT = 60;

export class ProposalService {
  constructor(private readonly repo: AppRepository) {}

  generate(input: GenerateProposalInput = {}): OrganizationProposal {
    const files = this.repo.files.list(input.folderId, input.limit ?? 400);
    if (files.length === 0) {
      throw new Error("还没有可用于生成建议的索引文件，请先扫描文件夹");
    }

    const activeRules = this.repo.rules.list(false);
    const items: OrganizationProposalItem[] = [];
    const proposalId = randomUUID();

    const duplicateItems = this.buildDuplicateTagItems(proposalId, files).slice(0, 12);
    items.push(...duplicateItems);

    for (const file of files) {
      if (items.length >= (input.limit ?? DEFAULT_LIMIT)) break;
      if (items.some((item) => item.fileId === file.id && item.action !== "tag")) continue;
      const item = this.buildOrganizationItem(proposalId, file, activeRules);
      if (item) items.push(item);
    }

    if (items.length === 0) {
      const keepItems = files.slice(0, 8).map((file) => this.buildKeepItem(proposalId, file, "当前文件风险较高或已经处在合理位置，建议先保留不动"));
      items.push(...keepItems);
    }

    const avgConfidence = items.reduce((sum, item) => sum + item.confidence, 0) / items.length;
    return this.repo.proposals.create({
      id: proposalId,
      title: `渐进整理建议 · ${new Date().toLocaleDateString("zh-CN")}`,
      folderId: input.folderId ?? null,
      status: "draft",
      reason: "基于本地索引、文件风险等级、下载/根目录堆积情况和用户偏好规则生成；执行前需要用户确认。",
      confidence: Number(avgConfidence.toFixed(2)),
      items
    });
  }

  private buildOrganizationItem(proposalId: string, file: FileRecord, rules: UserPreferenceRule[]): OrganizationProposalItem | null {
    const matchedRules = matchRules(file, rules);
    const protectionRule = matchedRules.find((rule) => rule.structuredRule.avoidMoving || rule.structuredRule.intent === "protect");
    if (protectionRule) {
      return this.buildKeepItem(proposalId, file, `匹配保护习惯：「${protectionRule.originalText}」`, [protectionRule.id]);
    }

    if (file.riskLevel === "high") {
      return this.buildKeepItem(proposalId, file, "高风险文件默认只索引不移动，避免破坏代码、配置或系统状态");
    }

    if (file.riskLevel === "medium" && !matchedRules.some((rule) => rule.structuredRule.targetTemplate)) {
      return this.buildKeepItem(proposalId, file, "中风险文件需要更明确的用户规则后再移动");
    }

    const specificRule = matchedRules.find((rule) => rule.structuredRule.targetTemplate);
    if (specificRule?.structuredRule.targetTemplate) {
      return this.buildMoveItem(proposalId, file, specificRule.structuredRule.targetTemplate, `匹配用户习惯：「${specificRule.originalText}」`, 0.86, [specificRule.id]);
    }

    if (shouldSuggestMove(file)) {
      return this.buildMoveItem(proposalId, file, "{category}/{year}", "文件位于下载/根目录等容易堆积的位置，建议渐进归档到清晰分类", 0.74);
    }

    if (file.tags.length <= 2 && file.category !== "其他文件") {
      return {
        id: randomUUID(),
        proposalId,
        fileId: file.id,
        action: "tag",
        sourcePath: file.path,
        targetPath: null,
        reason: `为文件补充虚拟分类标签：${file.category}`,
        confidence: 0.62,
        status: "pending",
        warnings: [],
        appliedRuleIds: []
      };
    }

    return null;
  }

  private buildDuplicateTagItems(proposalId: string, files: FileRecord[]): OrganizationProposalItem[] {
    const byHash = new Map<string, FileRecord[]>();
    for (const file of files) {
      if (file.hashKind !== "content" || file.size === 0) continue;
      const group = byHash.get(file.contentHash) ?? [];
      group.push(file);
      byHash.set(file.contentHash, group);
    }

    const items: OrganizationProposalItem[] = [];
    for (const group of byHash.values()) {
      if (group.length < 2) continue;
      const sorted = [...group].sort((a, b) => a.path.length - b.path.length);
      for (const duplicate of sorted.slice(1)) {
        items.push({
          id: randomUUID(),
          proposalId,
          fileId: duplicate.id,
          action: "tag",
          sourcePath: duplicate.path,
          targetPath: null,
          reason: `检测到疑似重复文件，原始位置保留；先添加“重复待确认”虚拟标签`,
          confidence: 0.82,
          status: "pending",
          warnings: ["重复文件不自动删除或移动"],
          appliedRuleIds: []
        });
      }
    }
    return items;
  }

  private buildMoveItem(
    proposalId: string,
    file: FileRecord,
    template: string,
    reason: string,
    confidence: number,
    appliedRuleIds: string[] = []
  ): OrganizationProposalItem {
    const targetPath = join(dirname(file.path), "__SmartOrganized", renderTemplate(template, file), basename(file.path));
    const warnings = file.riskReasons.length > 0 ? [...file.riskReasons] : [];
    if (targetPath === file.path) warnings.push("目标路径与源路径相同");

    return {
      id: randomUUID(),
      proposalId,
      fileId: file.id,
      action: "move",
      sourcePath: file.path,
      targetPath,
      reason,
      confidence,
      status: "pending",
      warnings,
      appliedRuleIds
    };
  }

  private buildKeepItem(proposalId: string, file: FileRecord, reason: string, appliedRuleIds: string[] = []): OrganizationProposalItem {
    return {
      id: randomUUID(),
      proposalId,
      fileId: file.id,
      action: "keep",
      sourcePath: file.path,
      targetPath: null,
      reason,
      confidence: 0.68,
      status: "pending",
      warnings: file.riskReasons,
      appliedRuleIds
    };
  }
}

function shouldSuggestMove(file: FileRecord): boolean {
  if (file.riskLevel !== "low") return false;
  if (file.path.includes("__SmartOrganized")) return false;
  if (isLikelyDownloadFolder(file.path)) return true;
  if (isRootLooseFile(file)) return true;
  if (dirname(file.relativePath).split(/[\\/]/).length <= 1 && ["财务票据", "合同协议", "文档资料", "图片素材", "压缩包"].includes(file.category)) {
    return true;
  }
  return false;
}

function matchRules(file: FileRecord, rules: UserPreferenceRule[]): UserPreferenceRule[] {
  const haystack = `${file.name} ${file.relativePath} ${file.category} ${file.summary} ${file.tags.join(" ")}`.toLowerCase();
  return rules.filter((rule) => {
    if (!rule.enabled) return false;
    if (rule.structuredRule.keywords.length === 0) return true;
    return rule.structuredRule.keywords.some((keyword) => haystack.includes(keyword.toLowerCase()));
  });
}

function renderTemplate(template: string, file: FileRecord): string {
  const year = new Date(file.modifiedAt).getFullYear().toString();
  const company = inferCompany(file) ?? "未识别公司";
  const project = inferProject(file) ?? "未识别项目";
  return template
    .replaceAll("{category}", safeSegment(file.category))
    .replaceAll("{year}", year)
    .replaceAll("{company}", safeSegment(company))
    .replaceAll("{project}", safeSegment(project))
    .split(/[\\/]/)
    .map(safeSegment)
    .filter(Boolean)
    .join("/");
}

function inferCompany(file: FileRecord): string | null {
  const match = `${file.name} ${file.summary}`.match(/(?:公司|客户|client|company)[:：\s_-]*([\u4e00-\u9fa5A-Za-z0-9]{2,24})/i);
  return match?.[1] ?? null;
}

function inferProject(file: FileRecord): string | null {
  const parts = file.relativePath.split(/[\\/]/).filter(Boolean);
  const projectPart = parts.find((part) => /(project|项目|prd|需求)/i.test(part));
  if (projectPart) return projectPart;
  const match = file.name.match(/(?:项目|project|prd)[-_ ]?([\u4e00-\u9fa5A-Za-z0-9]{2,24})/i);
  return match?.[1] ?? null;
}

